<script setup lang="ts">import type {Run} from '../types/domain';import {attemptLabel,recoveryLabel,failureReason} from '../utils/runs';import {short} from '../utils/format';defineProps<{runs:Run[];current:Run}>()</script><template><section class="attempts"><h2>尝试记录 / 同一冻结情景</h2><p class="muted">并发申请复用同一活动运行；失败记录保留，重试新增尝试并从页面指向原运行。成功结果和已批准报告不受重试影响。</p><div class="table-scroll"><table><thead><tr><th>运行</th><th>状态</th><th>尝试</th><th>恢复</th><th>失败原因</th><th>创建时间</th></tr></thead><tbody><tr v-for="a in runs" :key="a.id" :class="{current:a.id===current.id}"><td class="mono">{{short(a.id)}}<span v-if="a.retry_of"> ← {{short(a.retry_of)}}</span></td><td>{{a.status}}</td><td>{{attemptLabel(a)}}</td><td>{{recoveryLabel(a)}}</td><td>{{failureReason(a)||'—'}}</td><td>{{a.created_at}}</td></tr></tbody></table></div></section></template>
